import { rpc } from "@stellar/stellar-sdk";
import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { STELLAR_MAX_CONSECUTIVE_FAILURES, STELLAR_RETRY_BACKOFF_MS } from "../../src/constants.js";
import { SubmissionTimeoutError } from "../../src/errors.js";

// Mock the entire stellar.ts module to expose pollTransactionStatus for testing
// and to control its dependencies.
// We need to mock the constants to speed up tests.
vi.mock("../../src/constants.js", async (importOriginal) => {
  const actual = await importOriginal<typeof import("../../src/constants.js")>();
  return {
    ...actual,
    STELLAR_CONFIRMATION_TIMEOUT_MS: 1000, // Shorten timeout for tests
    STELLAR_RETRY_BACKOFF_MS: 10, // Shorten backoff for tests
    STELLAR_MAX_CONSECUTIVE_FAILURES: 3, // Shorten max failures for tests
  };
});

// Import the actual pollTransactionStatus after mocking constants
import { pollTransactionStatus } from "../../src/chains/stellar.js";

describe("pollTransactionStatus", () => {
  let mockServer: rpc.Server;
  const testHash = "test_tx_hash_123";

  beforeEach(() => {
    mockServer = {
      getTransaction: vi.fn(),
    } as unknown as rpc.Server;
    vi.useFakeTimers();
  });

  afterEach(() => {
    vi.restoreAllMocks();
    vi.useRealTimers();
  });

  it("should resolve with hash if transaction succeeds immediately", async () => {
    (mockServer.getTransaction as vi.Mock).mockResolvedValueOnce({ status: "SUCCESS" });

    const promise = pollTransactionStatus(mockServer, testHash);
    await vi.advanceTimersByTime(0); // Allow immediate promise resolution

    await expect(promise).resolves.toBe(testHash);
    expect(mockServer.getTransaction).toHaveBeenCalledTimes(1);
    expect(mockServer.getTransaction).toHaveBeenCalledWith(testHash);
  });

  it("should resolve with hash after N-1 transient failures then success", async () => {
    const maxFailures = STELLAR_MAX_CONSECUTIVE_FAILURES;
    for (let i = 0; i < maxFailures - 1; i++) {
      (mockServer.getTransaction as vi.Mock).mockRejectedValueOnce(new Error(`Transient error ${i + 1}`));
    }
    (mockServer.getTransaction as vi.Mock).mockResolvedValueOnce({ status: "SUCCESS" });

    const promise = pollTransactionStatus(mockServer, testHash);

    // Advance timers for each retry + the final success check
    for (let i = 0; i < maxFailures; i++) {
      await vi.advanceTimersByTime(STELLAR_RETRY_BACKOFF_MS);
    }

    await expect(promise).resolves.toBe(testHash);
    expect(mockServer.getTransaction).toHaveBeenCalledTimes(maxFailures);
    expect(mockServer.getTransaction).toHaveBeenCalledWith(testHash);
  });

  it("should reject with SubmissionTimeoutError if always throwing transient errors", async () => {
    const maxFailures = STELLAR_MAX_CONSECUTIVE_FAILURES;
    for (let i = 0; i < maxFailures + 1; i++) { // Throw one more than max to trigger timeout
      (mockServer.getTransaction as vi.Mock).mockRejectedValue(new Error(`Always failing error ${i + 1}`));
    }

    const promise = pollTransactionStatus(mockServer, testHash);

    // Advance timers enough to exceed max consecutive failures
    for (let i = 0; i < maxFailures + 1; i++) {
      await vi.advanceTimersByTime(STELLAR_RETRY_BACKOFF_MS);
    }

    await expect(promise).rejects.toThrow(SubmissionTimeoutError);
    await expect(promise).rejects.toHaveProperty("hash", testHash);
    expect(mockServer.getTransaction).toHaveBeenCalledTimes(maxFailures + 1); // Max failures + 1 attempt that triggers the error
  });

  it("should reject with SubmissionTimeoutError if timeout reached without success", async () => {
    (mockServer.getTransaction as vi.Mock).mockResolvedValue({ status: "PENDING" }); // Never succeeds

    const promise = pollTransactionStatus(mockServer, testHash);

    // Advance timers past the STELLAR_CONFIRMATION_TIMEOUT_MS (mocked to 1000ms)
    await vi.advanceTimersByTime(1000 + STELLAR_RETRY_BACKOFF_MS); // Timeout + one last poll interval

    await expect(promise).rejects.toThrow(SubmissionTimeoutError);
    await expect(promise).rejects.toHaveProperty("hash", testHash);
    // Number of calls depends on the mocked timeout and backoff
    expect(mockServer.getTransaction).toHaveBeenCalledWith(testHash);
    expect(mockServer.getTransaction.mock.calls.length).toBeGreaterThan(0);
  });

  it("should reject immediately if transaction status is FAILED", async () => {
    (mockServer.getTransaction as vi.Mock).mockResolvedValueOnce({ status: "FAILED" });

    const promise = pollTransactionStatus(mockServer, testHash);
    await vi.advanceTimersByTime(0); // Allow immediate promise resolution

    await expect(promise).rejects.toThrow(`Stellar transaction ${testHash} failed`);
    expect(mockServer.getTransaction).toHaveBeenCalledTimes(1);
    expect(mockServer.getTransaction).toHaveBeenCalledWith(testHash);
  });

  it("should reset consecutive failures counter on success after transient errors", async () => {
    const maxFailures = STELLAR_MAX_CONSECUTIVE_FAILURES;
    // Fail once
    (mockServer.getTransaction as vi.Mock).mockRejectedValueOnce(new Error("Transient error 1"));
    // Succeed
    (mockServer.getTransaction as vi.Mock).mockResolvedValueOnce({ status: "SUCCESS" });
    // Then fail again (should not trigger immediate timeout if counter reset)
    (mockServer.getTransaction as vi.Mock).mockRejectedValueOnce(new Error("Transient error 2"));
    // Then succeed again
    (mockServer.getTransaction as vi.Mock).mockResolvedValueOnce({ status: "SUCCESS" });


    const promise = pollTransactionStatus(mockServer, testHash);

    // First failure
    await vi.advanceTimersByTime(STELLAR_RETRY_BACKOFF_MS);
    // First success (resets counter)
    await vi.advanceTimersByTime(STELLAR_RETRY_BACKOFF_MS);
    // Second failure
    await vi.advanceTimersByTime(STELLAR_RETRY_BACKOFF_MS);
    // Second success
    await vi.advanceTimersByTime(STELLAR_RETRY_BACKOFF_MS);


    await expect(promise).resolves.toBe(testHash);
    expect(mockServer.getTransaction).toHaveBeenCalledTimes(4);
  });
});

