import { describe, it, expect } from 'vitest';
import {
  TransferError,
  AttestationNotReadyError,
  IrisRequestError,
  SubmissionTimeoutError,
  TransferErrorCode,
} from '../src/errors.js';

describe('Error Classes', () => {
  describe('TransferError', () => {
    const burnTxHash = '0x123abc';
    const message = 'Transfer failed due to an issue.';

    it('should construct with required fields', () => {
      const error = new TransferError(message, burnTxHash);
      expect(error).toBeInstanceOf(TransferError);
      expect(error).toBeInstanceOf(Error);
      expect(error.name).toBe('TransferError');
      expect(error.message).toBe(message);
      expect(error.burnTxHash).toBe(burnTxHash);
      expect(error.attestationHash).toBeUndefined();
      expect(error.code).toBeUndefined();
    });

    it('should construct with all optional fields', () => {
      const attestationHash = '0xdef456';
      const code: TransferErrorCode = 'ATTESTATION_NOT_READY';
      const error = new TransferError(message, burnTxHash, attestationHash, code);
      expect(error).toBeInstanceOf(TransferError);
      expect(error.name).toBe('TransferError');
      expect(error.message).toBe(message);
      expect(error.burnTxHash).toBe(burnTxHash);
      expect(error.attestationHash).toBe(attestationHash);
      expect(error.code).toBe(code);
    });

    it('should construct with only attestationHash', () => {
      const attestationHash = '0xdef456';
      const error = new TransferError(message, burnTxHash, attestationHash);
      expect(error.attestationHash).toBe(attestationHash);
      expect(error.code).toBeUndefined();
    });

    it('should construct with only code (passing undefined for attestationHash)', () => {
      const code: TransferErrorCode = 'ATTESTATION_NOT_READY';
      const error = new TransferError(message, burnTxHash, undefined, code);
      expect(error.attestationHash).toBeUndefined();
      expect(error.code).toBe(code);
    });
  });

  describe('AttestationNotReadyError', () => {
    const burnTxHash = '0x789ghi';
    const message = 'Attestation not ready yet.';

    it('should construct with required fields', () => {
      const error = new AttestationNotReadyError(message, burnTxHash);
      expect(error).toBeInstanceOf(AttestationNotReadyError);
      expect(error).toBeInstanceOf(Error);
      expect(error.name).toBe('AttestationNotReadyError');
      expect(error.message).toBe(message);
      expect(error.burnTxHash).toBe(burnTxHash);
    });
  });

  describe('IrisRequestError', () => {
    const message = 'Iris service returned an error.';

    it('should construct with required message', () => {
